<script setup lang="ts">
import {ref,onMounted} from 'vue'
const props=defineProps<{prospectId:number;request:(path:string,body?:any,method?:string)=>Promise<any>}>()
const emit=defineEmits<{saved:[];close:[]}>()
const prospect=ref<any>(null),rows=ref<any[]>([]),page=ref(1),count=ref(0),busy=ref(false),error=ref(''),kind=ref('note'),body=ref(''),status=ref('in_progress'),callback=ref('')
const statuses:Record<string,string>={to_contact:'À contacter',in_progress:'En cours',callback:'À rappeler',interested:'Intéressé',not_interested:'Non intéressé',unreachable:'Non joint'}
let requestId=crypto.randomUUID()
function changed(){requestId=crypto.randomUUID()}
async function load(){busy.value=true;error.value='';try{prospect.value=await props.request(`work-queue/${props.prospectId}/`);const data=await props.request(`work-queue/${props.prospectId}/activities/?page=${page.value}`);rows.value=data.results;count.value=data.count}catch(e:any){error.value=e.message;prospect.value=null}finally{busy.value=false}}
async function save(){if(!prospect.value)return;busy.value=true;error.value='';try{await props.request(`work-queue/${props.prospectId}/activities/`,{request_id:requestId,revision:prospect.value.revision,kind:kind.value,body:body.value,...(kind.value==='qualification'?{status:status.value,callback_at:status.value==='callback'?callback.value:null}:{})});body.value='';changed();page.value=1;await load();emit('saved')}catch(e:any){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="crm-prospect-detail"><h3>Suivi du prospect {{prospect?.name||prospectId}}</h3><p v-if="error" role="alert">{{error}}</p><p v-if="prospect">Résultat commercial : {{prospect.commercial_label}} · Rappel : {{prospect.callback_at?new Date(prospect.callback_at).toLocaleString('fr-FR'):'Aucun'}}</p><p>Les observations commerciales ne modifient pas les résultats techniques des numéros. « Non joint » ne signifie pas « numéro invalide ».</p><form v-if="prospect" @submit.prevent="save" @input="changed" @change="changed"><fieldset :disabled="busy"><label>Action<select v-model="kind"><option value="note">Ajouter une note</option><option value="qualification">Renseigner le résultat commercial</option></select></label><template v-if="kind==='qualification'"><label>Résultat<select v-model="status"><option v-for="(label,key) in statuses" :key="key" :value="key">{{label}}</option></select></label><label v-if="status==='callback'">Rappel ISO 8601 avec décalage (ex. 2026-12-01T10:00:00-05:00)<input v-model="callback" required></label><p>Un résultat autre que « À rappeler » retire le rappel courant, dont la date reste conservée dans l’historique.</p></template><label>Note ou justification<textarea v-model="body" required maxlength="3000"></textarea></label><button class="primary">Enregistrer dans l’historique</button></fieldset></form><button class="secondary" :disabled="busy" @click="load">Recharger la fiche et sa version</button><h4>Historique des observations</h4><article v-for="row in rows" :key="row.id"><small>{{new Date(row.created_at).toLocaleString('fr-FR')}} · {{row.author_role}} {{row.author_portal_id}} · {{row.kind==='note'?'Note':'Qualification'}}</small><p style="white-space:pre-wrap">{{row.body}}</p><p v-if="row.changes.after">{{statuses[row.changes.before.status]||row.changes.before.status}} → {{statuses[row.changes.after.status]||row.changes.after.status}} · Rappel : {{row.changes.after.callback_at?new Date(row.changes.after.callback_at).toLocaleString('fr-FR'):'Aucun'}}</p><p v-if="row.changes.before?.callback_at">Ancien rappel : {{new Date(row.changes.before.callback_at).toLocaleString('fr-FR')}}</p></article><p>{{count}} observation(s) · page {{page}}</p><button class="secondary" :disabled="busy||page===1" @click="page--;load()">Précédent</button><button class="secondary" :disabled="busy||page*25>=count" @click="page++;load()">Suivant</button><button class="secondary" :disabled="busy" @click="emit('close')">Fermer</button></section></template>
